# ---------- Legacy KiCad symbol cache ----------
def sym_def(name, ref, w, h, pins):
    # pins: (name,num,x,y,len,orient,etype)
    s=[f'DEF {name} {ref} 0 40 Y Y 1 F N',
       f'F0 "{ref}" 0 {h//2+100} 50 H V C CNN',
       f'F1 "{name}" 0 {-h//2-100} 50 H V C CNN',
       'DRAW', f'S {-w//2} {h//2} {w//2} {-h//2} 0 1 12 f']
    for p in pins:
        pn,num,x,y,l,ori,etype=p
        s.append(f'X {pn} {num} {x} {y} {l} {ori} 35 35 1 1 {etype}')
    s += ['ENDDRAW','ENDDEF','']
    return '\n'.join(s)

